const body = $json.body || $json;
const pregunta = String(body.pregunta || '').trim();

if (!pregunta) throw new Error('La pregunta no puede estar vacía');

const arr = v => Array.isArray(v) ? v : (v ? [v] : []);

return {
  json: {
    id_consulta: body.id_consulta ?? body.idConsulta ?? null,
    pregunta,
    nivel_experiencia: body.nivel_experiencia || body.nivelExperiencia || 'Principiante',
    area_interes: body.area_interes || body.areaInteres || 'General',
    cursos_previos: arr(body.cursos_previos || body.cursosPrevios),
    contexto_previo: body.contexto_previo || body.contextoPrevio || '',
    umbral: Number(body.umbral ?? 0.40)
  }
};

const d = $json;
const p = (d.pregunta || '').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .trim();

const isGreeting = /^(hola|buenas|buen dia|buenos dias|buenas tardes|buenas noches|hey|que tal|saludos|que mas|como estas|como te va)[\s!.,?]*$/i.test(p)
  || /^(hola|buenas|buenos dias|buenas tardes|buenas noches)[\s,]+(asesor|rutaia|amigo|como estas|que tal)/i.test(p);

const isThanks = /^(muchas\s+)?gracias[\s!.,?]*$/i.test(p)
  || /^(ok|vale|perfecto|entendido|excelente|listo)[\s,]+(gracias|muchas gracias)[\s!.,?]*$/i.test(p)
  || /^(muchas\s+)?gracias\s+(asesor|rutaia)[\s!.,?]*$/i.test(p);

const isFarewell = /^(adios|chao|hasta luego|nos vemos|hasta pronto|que tengas buen dia)[\s!.,?]*$/i.test(p);

const isAboutRutaIA = /\bruta\s*ia\b/.test(p) || /\b(esta plataforma|este asesor|esta pagina|este sistema|este chatbot|este bot)\b/.test(p);
const isIdentityQuestion = /\b(que es|quien es|como funciona|que hace|para que sirve|para que es|que funcion|cual es la funcion|que utilidad|proposito|objetivo|mision|de que trata|como me ayuda|en que me ayuda|que puedo hacer|que ofreces|que sabes hacer)\b/.test(p);

const identitySelfPatterns = [
  /\bquien eres\b/,
  /\bque eres\b/,
  /\bque puedes hacer\b/,
  /\bcomo me puedes ayudar\b/,
  /\bpara que sirves\b/,
  /\bcual es tu funcion\b/,
  /\bque funcion cumples\b/,
  /\bque funcion tienes\b/
];

const catalog = [
  /\b(cuales|que)\s+son\s+(todos\s+)?(los\s+)?cursos\b/,
  /\bque\s+cursos\s+(hay|tienen|ofrecen|estan disponibles)\b/,
  /\b(catalogo|lista)\s+(de\s+)?cursos\b/,
  /\bmu[eé]strame\s+(todos\s+)?los\s+cursos\b/,
  /\bdame\s+(todos\s+)?los\s+cursos\b/,
  /\bque\s+puedo\s+estudiar\b/,
  /\bque\s+opciones\s+de\s+formacion\s+tienen\b/
];

const outside = [
  /\b(pilotaje|avioneta|aviacion|gastronomia|cocina|medicina|derecho|odontologia|enfermeria|mecanica automotriz)\b/
];

let intent = 'search';
if (isGreeting) intent = 'greeting';
else if (isThanks) intent = 'thanks';
else if (isFarewell) intent = 'farewell';
else if ((isAboutRutaIA && isIdentityQuestion) || identitySelfPatterns.some(r => r.test(p))) intent = 'identity';
else if (catalog.some(r => r.test(p))) intent = 'catalog';
else if (outside.some(r => r.test(p))) intent = 'outside';

return { json: { ...d, intent } };

const d = $json;
const apiKey = $env.GEMINI_API_KEY;

const prompt = `Eres RutaIA Asesor, el orientador académico y vocacional inteligente de la plataforma educativa RutaIA.
Tu rol es orientar a los estudiantes en su trayectoria formativa con calidez, cercanía, empatía y profesionalismo humano.

INSTRUCCIONES CLAVE:
1. Responde de forma muy natural, empática y conversacional, adaptándote exactamente a lo que el estudiante te dice o pregunta.
2. Si te pregunta "¿cómo estás?" o "¿cómo te va?", salúdalo amablemente, dile cómo te encuentras con entusiasmo por poder orientarlo, y pregúntale cómo está él o en qué meta académica está pensando.
3. Si te saluda ("hola", "buenas", "buenos días"), dale una bienvenida amigable y cercana, y motívalo a contarte qué le gustaría aprender hoy.
4. Si te agradece ("gracias"), responde con calidez y entusiasmo de seguir apoyándolo.
5. Si te pregunta qué es RutaIA o quién eres, explícale tu propósito institucional de forma clara y accesible.
6. Mantén siempre tu identidad como asesor de RutaIA: recuérdale que estás listo para ayudarle a explorar áreas tecnológicas (programación, inteligencia artificial, desarrollo web, DevOps, ciberseguridad, bases de datos) o a revisar el catálogo institucional de cursos.
7. Sé conciso pero humano (2 a 3 párrafos breves o viñetas cuando amerite). No suenes como un menú telefónico ni repitas textos acartonados.

DATOS DEL ESTUDIANTE:
Nivel: ${d.nivel_experiencia || 'No especificado'}
Área de interés: ${d.area_interes || 'Tecnología'}

MENSAJE DEL ESTUDIANTE:
${d.pregunta}

Responde directamente al estudiante:`;

let respuestaTexto = '';
const models = ['gemini-flash-lite-latest', 'gemma-4-26b-a4b-it', 'gemini-flash-latest'];

for (const model of models) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
      headers: { 'Content-Type': 'application/json' },
      body: {
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        generationConfig: { temperature: 0.7, maxOutputTokens: 1024 }
      },
      json: true
    });
    const text = res?.candidates?.[0]?.content?.parts?.[0]?.text;
    if (text && text.trim()) {
      respuestaTexto = text.trim();
      break;
    }
  } catch (err) {}
}

if (!respuestaTexto) {
  if (d.intent === 'greeting') {
    respuestaTexto = `¡Hola! 👋 Qué alegría saludarte. Te doy la bienvenida a **RutaIA**, tu orientador académico inteligente.\n\nEstoy aquí para acompañarte a descubrir tu camino formativo según tus metas e intereses en tecnología (como programación, IA, desarrollo web o cloud).\n\n¿En qué estás pensando enfocarte hoy o qué te gustaría aprender? ¡Te escucho!`;
  } else if (d.intent === 'thanks') {
    respuestaTexto = `¡Con mucho gusto! 😊 Me alegra un montón poder orientarte. Si tienes más dudas o quieres explorar nuevas áreas, aquí estaré listo para ayudarte. ¡Muchos éxitos!`;
  } else if (d.intent === 'farewell') {
    respuestaTexto = `¡Hasta pronto! 👋 Que tengas un excelente día. Recuerda que siempre puedes volver a consultar a **RutaIA** cuando lo necesites.`;
  } else {
    respuestaTexto = `RutaIA es tu plataforma inteligente de orientación académica vocacional. Mi misión es guiarte para descubrir los cursos ideales según tus intereses y metas profesionales en tecnología.`;
  }
}

return {json: {
  id_consulta: d.id_consulta,
  pregunta: d.pregunta,
  respuesta: respuestaTexto,
  fuentes: [],
  similitudes: [],
  estado_final: "Respondida",
  intent: d.intent
}};

